// Contract (input): { level, event, correlationId, attrs }
// Emits a normalized, secret-safe log line. Swap the sink for CloudWatch/Datadog/Loki.
const redact = (v) => {
  if (typeof v !== 'string') return v;
  return v.replace(/(sk-[A-Za-z0-9-]{6})[A-Za-z0-9-]+/g, '$1***')
          .replace(/AKIA[0-9A-Z]{16}/g, 'AKIA****');
};
const input = $json || {};
const safeAttrs = {};
for (const [k, val] of Object.entries(input.attrs || {})) safeAttrs[k] = redact(val);
const record = {
  ts: new Date().toISOString(),
  level: input.level || 'info',
  event: input.event || 'unspecified',
  correlationId: input.correlationId || null,
  attrs: safeAttrs
};
console.log(JSON.stringify(record));
return [{ json: record }];
